// Receiver returns 202 {accepted:true,eventId:'...',duplicate:false}
const data = msg.payload;
if (msg.statusCode === 202 && data && data.accepted === true && data.eventId === msg.eventId) {
    node.status({ fill:'green', shape:'dot', text: 'HTTP 202 accepted' });
    return [null, {payload:{status:'accepted',eventId:msg.eventId,duplicate:!!data.duplicate}}];
}
node.status({ fill:'red', shape:'ring', text:'HTTP error '+(msg.statusCode || 'unknown') });
node.error('HTTP notification NOT accepted: '+(msg.statusCode || 'no status'), msg);
return [ {payload:{status:'failed',statusCode:msg.statusCode || null,eventId:msg.eventId,response:data}}, null ];

const circuits = [
    { id: "ns=2;i=6074", name: "Circuit 1" },
    { id: "ns=2;i=6061", name: "Circuit 2" }
];

// Das Paket node-red-contrib-opcua liefert bei payload="ALL"
// ein Array von OPC-UA DataValue-Objekten auf Ausgang 1.
const data = msg.payload;
if (!Array.isArray(data) || data.length !== circuits.length) {
    node.status({ fill: "yellow", shape: "ring", text: "ungueltige Read-Antwort" });
    return [null, { payload: "OPC UA: Erwartet werden genau zwei DataValues.", received: data }];
}

// Falls in settings.js ein Context-Store namens 'file' existiert,
// diesen fuer neustartuebergreifende Flankenspeicherung verwenden.
let useFileStore = true;
let previous;
try {
    previous = context.get("configurationErrorStates", "file") || {};
} catch (err) {
    useFileStore = false;
    previous = context.get("configurationErrorStates") || {};
}

function isGood(status) {
    if (status === 0 || status === "Good") return true;
    if (status === null || status === undefined) return false;
    if (typeof status === "object") {
        if (typeof status.value === "number") return status.value === 0;
        if (status.name === "Good") return true;
        if (typeof status.toString === "function") return status.toString() === "Good";
    }
    return false;
}

const outgoing = [];
const problems = [];
for (let i = 0; i < circuits.length; i++) {
    const item = data[i];
    const circuit = circuits[i];
    if (!item || !isGood(item.statusCode) || !item.value ||
        typeof item.value.value !== "boolean") {
        problems.push(circuit.name + ": Status nicht Good oder Wert nicht boolean");
        continue;  // Fehlmessungen duerfen keine Entwarnung ausloesen.
    }

    const current = item.value.value;
    const old = previous[circuit.id];
    const isAlarm = current === true && old !== true;
    const isClear = current === false && old === true;
    previous[circuit.id] = current;

    // Beim ersten gueltigen Lesen wird ein bereits aktiver Fehler
    // sofort gemeldet; false erzeugt beim Initialisieren keine Mail.
    if (!isAlarm && !isClear) continue;

    const time = new Date().toLocaleString("de-DE", { timeZone: "Europe/Berlin" });
    outgoing.push({
        topic: isAlarm
            ? "[ConfigurationError] ALARM - " + circuit.name
            : "[ConfigurationError] ENTWARNUNG - " + circuit.name,
        payload: [
            isAlarm ? "ALARM: ConfigurationError erkannt." : "ENTWARNUNG / Quittierung: ConfigurationError zurueckgesetzt.",
            "",
            "Circuit: " + circuit.name,
            "OPC-UA NodeId: " + circuit.id,
            "Aktueller Wert: " + current,
            "Zeitpunkt der Erkennung: " + time + " (Europe/Berlin)",
            "",
            "Automatische Meldung aus Node-RED (60-Sekunden-Abfrage).",
            "Diese Entwarnung ist keine serverseitige OPC-UA-Acknowledge-Aktion."
        ].join("\n"),
        circuitId: circuit.id,
        configurationError: current
    });
}

if (useFileStore) {
    context.set("configurationErrorStates", previous, "file");
} else {
    context.set("configurationErrorStates", previous);
}

if (problems.length) {
    node.status({ fill: "yellow", shape: "ring", text: "Lesefehler bei " + problems.length + " Circuit(s)" });
} else {
    const active = circuits.filter(c => previous[c.id] === true).length;
    node.status({ fill: active ? "red" : "green", shape: "dot",
        text: active ? active + " ConfigurationError aktiv" : "beide Circuits OK" });
}
return [outgoing.length ? outgoing : null,
        problems.length ? { payload: problems.join("; ") } : null];

// Der OPC-UA-Client nutzt die Aktion "readmultiple".
// Wir loeschen nur die interne Merkliste des Clients und tragen die
// zwei NodeIDs bei jedem Zyklus erneut ein (ohne OPC-UA-Lesezugriff).
// Erst die letzte Nachricht fuehrt EINEN gemeinsamen OPC-UA Read aus.
node.send({ topic: "clearitems" });
node.send({ topic: "ns=2;i=6074;datatype=Boolean" });
node.send({ topic: "ns=2;i=6061;datatype=Boolean" });
node.send({ topic: "readmultiple", payload: "ALL" });
return null;

// Convert the EXISTING edge-detection result into the webhook format
// expected by the Email Node-RED receiver.
// No SMTP sender/recipient here. No OPC-UA credentials are transmitted.
const url = 'http://dpn-svr-iot.rah.polipol.intra/node-red-test/asiconfigurationerror/email';
if (typeof url !== 'string' || !/^https?:\/\//i.test(url)) {
    node.error('ALARM_WEBHOOK_URL is missing/invalid', msg);
    node.status({ fill:'red', shape:'ring', text:'HTTP ENV missing' });
    return null;
}

const eventId = 'GOR-ASI-SZW1-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 12);
const isTest = msg._testWebhook === true;
let event;
if (isTest) {
    event = { eventId, source:'GOR-ASI-SZW1', circuit:'TEST',
              nodeId:null, state:null, eventType:'TEST',
              observedAt:new Date().toISOString() };
} else {
    const circuit = { 'ns=2;i=6074':'Circuit 1', 'ns=2;i=6061':'Circuit 2' }[msg.circuitId];
    if (!circuit || typeof msg.configurationError !== 'boolean') {
        node.error('Unsupported circuit or invalid Boolean edge', msg);
        return null;
    }
    event = { eventId, source:'GOR-ASI-SZW1', circuit,
              nodeId:msg.circuitId, state:msg.configurationError,
              eventType:msg.configurationError ? 'ALARM' : 'RECOVERY',
              observedAt:new Date().toISOString() };
}
msg.method = 'POST';
msg.url = url;
msg.headers = { 'Content-Type':'application/json' };
msg.payload = event; // HTTP Request serializes JSON using Content-Type header
msg.eventId = eventId;
delete msg._testWebhook;
return msg;
